,formula_kcal_cut_prefix:970,formula_kcal_cut_suffix:971,formula_kcal_cut_current:972,formula_kcal_bulk:973,formula_kcal_hint:974,goals_dialog_title:975,day_note:976,no_note:977,edit_note:978,note_hint:979,meal_note:980,meal_note_hint:981,meal_note_checklist_sub:982,meal_note_add_line:983,meal_note_line_hint:984,meal_note_remove_line:985,meal_expand_inline:986,meal_open_tracked:987,meal_add_menu:988,meal_tracked_popup_title:989,meal_tracked_empty:990,track_edit_mode_g:991,track_edit_mode_kcal:992,track_edit_portion_hint:993,track_portion_manual_title:994,track_mode_short_protein:995,track_mode_short_carbs:996,track_mode_short_fat:997,track_edit_grams_only:998,meal_compact_gestures_hint:999,alltag_distribution:1000,alltag_performance:1001,alltag_relaxed:1002,alltag_distribution_hint:1003,alltag_kcal_change_label:1004,alltag_apply:1005,alltag_applied_msg:1006,meal_order_title:1007,meal_order_hint:1008,meal_order_free_hint:1009,meal_order_free_sub:1010,meal_order_rename:1011,meal_rename_title:1012,meal_rename_label:1013,meal_order_block_hint:1014,meal_order_snacks_locked:1015,commitment_title:1016,commitment_body:1017,commitment_quote:1018,commitment_checkbox:1019,commitment_confirm:1020,commitment_decline:1021,mode_aggressive_badge:1022,mode_aggressive_sub:1023,activity_level_title:1024,activity_level_hint:1025,activity_level_very_active:1026,activity_level_normal:1027,activity_level_low:1028,formula_activity_line:1029,cut_movement_block_title:1030,cut_movement_block_hint:1031,cut_want_label:1032,cut_style_more_cardio:1033,cut_style_standard:1034,cut_style_less_move:1035,cut_style_hint:1036,cut_baseline_steps_title:1037,cut_baseline_steps_body:1038,cut_steps_short:1039,cut_baseline_kcal_foot:1040,cut_day_card_title:1041,cut_day_override_on:1042,cut_day_uses_baseline:1043,cut_day_kcal_line:1044,cut_day_reset_baseline:1045,advanced_preset:1046,advanced_preset_cut:1047,advanced_preset_maintain:1048,advanced_preset_bulk:1049,advanced_preset_hint:1050,apply_preset:1051,ble